    --blue:#1a3f8f;
    --yellow:#f2c40f;
    --black:#101010;
    --white:#f7f5f0;
    --grey:#8a8a86;
    --line:clamp(6px, 1.1vw, 12px);
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    background:var(--white);
    color:var(--black);
    font-family:"Archivo", Arial, Helvetica, sans-serif;
    line-height:1.55;
    -webkit-font-smoothing:antialiased;
  }
  .mono{font-family:"IBM Plex Mono", ui-monospace, monospace}

  /* ---------- masthead: a Mondrian bar ---------- */
  header.mast{
    display:grid;
    grid-template-columns: 4fr 1.2fr 1fr 2fr;
    grid-template-rows: 1fr 1fr;
    height:clamp(120px, 22vh, 220px);
    border-bottom:var(--line) solid var(--black);
  }
  header.mast > div{border-right:var(--line) solid var(--black); border-bottom:var(--line) solid var(--black)}
  header.mast > div:nth-child(4){border-right:none}
