  .m-yellow{grid-column:3;grid-row:1;background:var(--yellow)}
  .m-black{grid-column:4;grid-row:1;background:var(--black);display:flex;align-items:center;padding:0 1.2rem}
  .m-black span{color:var(--white);font-weight:700;letter-spacing:.14em;text-transform:uppercase;font-size:clamp(.7rem,1.4vw,1rem)}
  .m-blue{grid-column:1;grid-row:2;background:var(--blue)}
  .m-white2{grid-column:2 / 4;grid-row:2;background:var(--white);display:flex;align-items:center;justify-content:center}
  .m-white2 span{font-size:clamp(.65rem,1.2vw,.85rem);letter-spacing:.08em;color:var(--black)}
  .m-white2 span b{font-weight:700}

