  section.picture{
    max-width:1100px;
    margin:0 auto;
    padding:clamp(2rem,5vw,4rem) clamp(1rem,4vw,3rem) 0;
  }
  .frame{
    border:var(--line) solid var(--black);
    background:var(--white);
    display:grid;
    /* faithful layout: large red square top right, small blue square bottom left,
       small yellow rectangle bottom right, thick black lines on white ground */
    grid-template-columns: 1.1fr 1fr 1fr;
    grid-template-rows: 1.4fr 1fr;
    aspect-ratio: 1 / 1;
    max-width:640px;
    margin:0 auto;
  }
  .frame > div{border-right:var(--line) solid var(--black); border-bottom:var(--line) solid var(--black)}
  .frame > div:nth-child(3n){border-right:none}
  .frame > div:nth-child(n+4){border-bottom:none}
  .cell{position:relative}
  .cell-red{grid-column:3;grid-row:1;background:var(--red)}
  .cell-white1{grid-column:1;grid-row:1;background:var(--white)}
  .cell-white2{grid-column:2;grid-row:1;background:var(--white)}
  .cell-blue{grid-column:1;grid-row:2;background:var(--blue)}
  .cell-white3{grid-column:2;grid-row:2;background:var(--white)}
  .cell-yellow{grid-column:3;grid-row:2;background:var(--yellow)}
